-- Services
INSERT INTO public.services (slug, title, description, icon, content_html, h1_override, meta_title, meta_description, sort_order) VALUES
  ('interior-painting', 'Interior Painting', 'Walls, ceilings, doors and trims painted with premium low-odour paints and a clean, sharp finish — for apartments, villas and offices.', 'roller', '<h2>Interior painting that looks sharp and lasts</h2>
<p><strong>Fresh walls. Spotless sofas.</strong></p>
<p>Whether it''s one feature wall or a whole villa, our painters prepare every surface properly — filling cracks, sanding and priming — before applying two even coats of premium paint.</p><p>We cover floors and furniture, keep the dust down and clean up at the end of every day, so you can keep living in your home while we work.</p>
<h3>What Our Interior Painting Covers</h3>
<ul><li><p><strong>Walls &amp; ceilings</strong> Two coats of emulsion in matt, silk or satin, with clean cut-in lines at ceilings and skirting.</p></li><li><p><strong>Doors, frames &amp; trims</strong> Wood and metal surfaces sanded and finished in enamel or water-based gloss.</p></li><li><p><strong>Feature &amp; accent walls</strong> Bold colours, two-tone walls and textured finishes to give a room character.</p></li><li><p><strong>Repairs &amp; preparation</strong> Crack filling, putty, sanding and stain-blocking primer for damp or smoke marks.</p></li></ul>
<h3>Packages &amp; Prices</h3>
<ul><li><p><strong>Studio apartment</strong> From AED 650 — walls &amp; ceilings, 2 coats, 1 day.</p></li><li><p><strong>1 bedroom apartment</strong> From AED 950 — walls &amp; ceilings, 2 coats, 1–2 days.</p></li><li><p><strong>2 bedroom apartment</strong> From AED 1,400 — includes putty patching and furniture covering.</p></li><li><p><strong>Villa interior</strong> From AED 3,500 — 3–5 bedrooms, doors and trims on request.</p></li></ul>
<p>Final prices are fixed after we see photos or inspect the space. <a href="/pricing">See the full price list</a>.</p>
<h3>How It Works</h3>
<ol><li><p><strong>Send photos or call</strong> Share the rooms, sofa size or area you need done by WhatsApp, phone or the quote form.</p></li><li><p><strong>Get a fixed price</strong> We send a clear quote, or visit for a free inspection on bigger painting jobs.</p></li><li><p><strong>We do the work</strong> Our uniformed team arrives on time, covers furniture and floors, and gets to work.</p></li><li><p><strong>Clean handover</strong> We tidy up, walk you through the finish and only leave when you''re happy.</p></li></ol>
<h3>Why Choose Matla Al Anwar</h3>
<ul><li><p><strong>Fixed, transparent prices</strong> no hidden charges after the quote</p></li><li><p><strong>Trained, uniformed team</strong> painters and cleaners who respect your home</p></li><li><p><strong>Premium materials</strong> Jotun, National Paints, Dulux and safe cleaning solutions</p></li><li><p><strong>Furniture &amp; floor protection</strong> everything covered before we start</p></li><li><p><strong>All 7 emirates</strong> covered from one point of contact</p></li></ul>
<h3 data-block="areas">Areas We Cover</h3>
<p><a href="/locations/dubai">Dubai</a> · <a href="/locations/abu-dhabi">Abu Dhabi</a> · <a href="/locations/sharjah">Sharjah</a> · <a href="/locations/ajman">Ajman</a> · <a href="/locations/ras-al-khaimah">Ras Al Khaimah</a> · <a href="/locations/fujairah">Fujairah</a> · <a href="/locations/umm-al-quwain">Umm Al Quwain</a></p>
<h3 data-block="faq">Frequently Asked Questions</h3>
<h4>How long does interior painting take?</h4><p>A studio or 1-bedroom apartment usually takes 1–2 days, a 2-bedroom about 2 days and a villa interior 3–6 days, depending on size and wall condition.</p>
<h4>Is the paint smell a problem?</h4><p>We use low-odour, low-VOC paints. Most families stay at home during the job — we simply work room by room and keep windows open or the AC running.</p>
<h4>Can I choose the colour and brand?</h4><p>Yes. We work with Jotun, National Paints and Dulux and can bring colour fans to your home. Changing from a dark to a light colour may need an extra coat.</p>
<h4>Do you fix cracks before painting?</h4><p>Yes. Minor cracks, nail holes and dents are filled, sanded and primed as part of the job. Larger repairs are quoted separately after inspection.</p>', 'Interior Painting in Dubai and Across the UAE', 'Interior Painting Services in Dubai & UAE | Matla Al Anwar', 'Professional interior painting in Dubai, Sharjah, Abu Dhabi & all UAE. Walls, ceilings, doors & feature walls with Jotun, National Paints or Dulux. Free inspection, fixed prices.', 1),
  ('exterior-painting', 'Exterior & Villa Painting', 'Weather-resistant coatings for villa facades, boundary walls and gates that stand up to UAE sun, sand and humidity.', 'home', '<h2>Exterior paint built for UAE weather</h2>
<p><strong>Fresh walls. Spotless sofas.</strong></p>
<p>Sun, sand and humidity are hard on exterior walls. We use weather-shield and elastomeric coatings designed for the Gulf climate, so your villa keeps its colour and stays protected for years.</p><p>Every job starts with pressure washing, crack repair and primer — the steps that make the difference between paint that peels in a summer and paint that lasts.</p>
<h3>What Our Exterior Painting Covers</h3>
<ul><li><p><strong>Villa facades</strong> Full exterior repaint with weather-resistant, UV-stable paint.</p></li><li><p><strong>Boundary &amp; garden walls</strong> Clean, crack-repaired and recoated to match or refresh your colour scheme.</p></li><li><p><strong>Gates, grills &amp; railings</strong> Rust treatment and enamel or metal paint for steel and iron.</p></li><li><p><strong>Pergolas &amp; wood</strong> Sanding, staining and varnish for wooden pergolas, doors and decking.</p></li></ul>
<h3>Packages &amp; Prices</h3>
<ul><li><p><strong>Boundary wall</strong> Priced per metre after inspection.</p></li><li><p><strong>Townhouse exterior</strong> From AED 3,000 depending on height and condition.</p></li><li><p><strong>Villa exterior</strong> From AED 5,000 — washing, repairs, primer and 2 coats.</p></li><li><p><strong>Gates &amp; metalwork</strong> From AED 400 — rust treatment and enamel.</p></li></ul>
<p>Final prices are fixed after we see photos or inspect the space. <a href="/pricing">See the full price list</a>.</p>
<h3>How It Works</h3>
<ol><li><p><strong>Send photos or call</strong> Share the rooms, sofa size or area you need done by WhatsApp, phone or the quote form.</p></li><li><p><strong>Get a fixed price</strong> We send a clear quote, or visit for a free inspection on bigger painting jobs.</p></li><li><p><strong>We do the work</strong> Our uniformed team arrives on time, covers furniture and floors, and gets to work.</p></li><li><p><strong>Clean handover</strong> We tidy up, walk you through the finish and only leave when you''re happy.</p></li></ol>
<h3>Why Choose Matla Al Anwar</h3>
<ul><li><p><strong>Fixed, transparent prices</strong> no hidden charges after the quote</p></li><li><p><strong>Trained, uniformed team</strong> painters and cleaners who respect your home</p></li><li><p><strong>Premium materials</strong> Jotun, National Paints, Dulux and safe cleaning solutions</p></li><li><p><strong>Furniture &amp; floor protection</strong> everything covered before we start</p></li><li><p><strong>All 7 emirates</strong> covered from one point of contact</p></li></ul>
<h3 data-block="areas">Areas We Cover</h3>
<p><a href="/locations/dubai">Dubai</a> · <a href="/locations/abu-dhabi">Abu Dhabi</a> · <a href="/locations/sharjah">Sharjah</a> · <a href="/locations/ajman">Ajman</a> · <a href="/locations/ras-al-khaimah">Ras Al Khaimah</a> · <a href="/locations/fujairah">Fujairah</a> · <a href="/locations/umm-al-quwain">Umm Al Quwain</a></p>
<h3 data-block="faq">Frequently Asked Questions</h3>
<h4>How long does exterior paint last in the UAE?</h4><p>With proper preparation and weather-shield paint, an exterior repaint typically looks good for 5–7 years before it needs refreshing.</p>
<h4>Do you need scaffolding?</h4><p>For most villas we use ladders and towers; scaffolding is arranged where needed and included in the quote.</p>
<h4>Can you paint in summer?</h4><p>Yes. We schedule exterior work for early mornings and late afternoons in the hottest months so the paint cures properly.</p>
<h4>Do you need community or landlord approval?</h4><p>Some communities require approval for colour changes. We''re happy to provide colour codes and a quote for your application.</p>', 'Exterior & Villa Painting in Dubai and Across the UAE', 'Exterior & Villa Painting Dubai | Weatherproof Paint | Matla Al Anwar', 'Villa exterior painting in Dubai, Abu Dhabi, Sharjah & RAK. Weather-shield paints for facades, boundary walls, gates & pergolas. Free site inspection, fixed price.', 2),
  ('apartment-painting', 'Apartment Move-In / Move-Out Painting', 'Fast repainting to get your security deposit back or make a new home feel fresh — usually finished in 1–2 days.', 'building', '<h2>Move-out painting that gets your deposit back</h2>
<p><strong>Fresh walls. Spotless sofas.</strong></p>
<p>Most UAE tenancy contracts ask you to return the apartment painted in its original colour. We repaint to landlord standard — usually a clean white or off-white — fill any nail holes and leave the place ready for handover inspection.</p><p>Moving in? We''ll freshen up the walls before your furniture arrives so you start with a clean, bright home.</p>
<h3>What''s Included</h3>
<ul><li><p><strong>Original-colour repaint</strong> Walls and ceilings returned to the landlord''s colour, usually white.</p></li><li><p><strong>Nail holes &amp; marks</strong> Holes from frames and TV mounts filled and sanded smooth.</p></li><li><p><strong>Fast turnaround</strong> Most studios and 1-bedrooms done in a single day.</p></li><li><p><strong>Clean handover</strong> Floors, sockets and windows cleaned of paint before we leave.</p></li></ul>
<h3>Packages &amp; Prices</h3>
<ul><li><p><strong>Studio</strong> From AED 650.</p></li><li><p><strong>1 bedroom</strong> From AED 950.</p></li><li><p><strong>2 bedroom</strong> From AED 1,400.</p></li><li><p><strong>3 bedroom</strong> From AED 1,900.</p></li></ul>
<p>Final prices are fixed after we see photos or inspect the space. <a href="/pricing">See the full price list</a>.</p>
<h3>How It Works</h3>
<ol><li><p><strong>Send photos or call</strong> Share the rooms, sofa size or area you need done by WhatsApp, phone or the quote form.</p></li><li><p><strong>Get a fixed price</strong> We send a clear quote, or visit for a free inspection on bigger painting jobs.</p></li><li><p><strong>We do the work</strong> Our uniformed team arrives on time, covers furniture and floors, and gets to work.</p></li><li><p><strong>Clean handover</strong> We tidy up, walk you through the finish and only leave when you''re happy.</p></li></ol>
<h3>Why Choose Matla Al Anwar</h3>
<ul><li><p><strong>Fixed, transparent prices</strong> no hidden charges after the quote</p></li><li><p><strong>Trained, uniformed team</strong> painters and cleaners who respect your home</p></li><li><p><strong>Premium materials</strong> Jotun, National Paints, Dulux and safe cleaning solutions</p></li><li><p><strong>Furniture &amp; floor protection</strong> everything covered before we start</p></li><li><p><strong>All 7 emirates</strong> covered from one point of contact</p></li></ul>
<h3 data-block="areas">Areas We Cover</h3>
<p><a href="/locations/dubai">Dubai</a> · <a href="/locations/abu-dhabi">Abu Dhabi</a> · <a href="/locations/sharjah">Sharjah</a> · <a href="/locations/ajman">Ajman</a> · <a href="/locations/ras-al-khaimah">Ras Al Khaimah</a> · <a href="/locations/fujairah">Fujairah</a> · <a href="/locations/umm-al-quwain">Umm Al Quwain</a></p>
<h3 data-block="faq">Frequently Asked Questions</h3>
<h4>Will the landlord accept your work?</h4><p>We paint to the standard landlords and property managers expect for handover. If they flag a touch-up, we come back and fix it.</p>
<h4>Can you work around my moving date?</h4><p>Yes. Tell us your handover date and we''ll schedule painting after your furniture is out, often the day before.</p>
<h4>Do you also clean the sofa or carpet before I move?</h4><p>Yes — many customers combine move-out painting with sofa, mattress or carpet cleaning. Ask for a combined quote.</p>', 'Move-In & Move-Out Apartment Painting in Dubai', 'Move-Out Painting Dubai | Apartment Painting for Deposit | Matla Al Anwar', 'Move-in & move-out apartment painting in Dubai, Sharjah & Ajman. Studio from AED 650, 1BR from AED 950. Landlord-standard white finish, done in 1–2 days.', 3),
  ('sofa-cleaning', 'Sofa Cleaning', 'Deep shampoo and hot-water extraction that lifts stains, odours and dust mites from fabric sofas — done at your home and dry in hours.', 'sofa', '<h2>Deep sofa cleaning at your home</h2>
<p><strong>Fresh walls. Spotless sofas.</strong></p>
<p>Dust, sweat, food spills and sand build up in sofa fabric faster than you think — especially in the UAE. Our technicians vacuum, pre-treat stains, shampoo and then rinse with hot-water extraction to pull the dirt out, not push it deeper.</p><p>We use fabric-safe, non-toxic solutions that are safe for children and pets, and powerful extraction machines so your sofa is dry in just a few hours.</p>
<h3>What Our Sofa Cleaning Covers</h3>
<ul><li><p><strong>Fabric sofas</strong> 2-seaters, 3-seaters, L-shapes, sofa beds and recliners.</p></li><li><p><strong>Stain removal</strong> Coffee, tea, juice, food, ink and pet stains treated individually.</p></li><li><p><strong>Odour &amp; dust mites</strong> Sanitising and deodorising to remove smells and allergens.</p></li><li><p><strong>Cushions &amp; pillows</strong> Seat and back cushions cleaned inside and out where covers allow.</p></li></ul>
<h3>Packages &amp; Prices</h3>
<ul><li><p><strong>3-seater sofa</strong> From AED 149.</p></li><li><p><strong>L-shape / 5–7 seater</strong> From AED 249.</p></li><li><p><strong>Armchair</strong> From AED 60.</p></li><li><p><strong>Sofa + carpet combo</strong> Ask for a combined price.</p></li></ul>
<p>Final prices are fixed after we see photos or inspect the space. <a href="/pricing">See the full price list</a>.</p>
<h3>How It Works</h3>
<ol><li><p><strong>Send photos or call</strong> Share the rooms, sofa size or area you need done by WhatsApp, phone or the quote form.</p></li><li><p><strong>Get a fixed price</strong> We send a clear quote, or visit for a free inspection on bigger painting jobs.</p></li><li><p><strong>We do the work</strong> Our uniformed team arrives on time, covers furniture and floors, and gets to work.</p></li><li><p><strong>Clean handover</strong> We tidy up, walk you through the finish and only leave when you''re happy.</p></li></ol>
<h3>Why Choose Matla Al Anwar</h3>
<ul><li><p><strong>Fixed, transparent prices</strong> no hidden charges after the quote</p></li><li><p><strong>Trained, uniformed team</strong> painters and cleaners who respect your home</p></li><li><p><strong>Premium materials</strong> Jotun, National Paints, Dulux and safe cleaning solutions</p></li><li><p><strong>Furniture &amp; floor protection</strong> everything covered before we start</p></li><li><p><strong>All 7 emirates</strong> covered from one point of contact</p></li></ul>
<h3 data-block="areas">Areas We Cover</h3>
<p><a href="/locations/dubai">Dubai</a> · <a href="/locations/abu-dhabi">Abu Dhabi</a> · <a href="/locations/sharjah">Sharjah</a> · <a href="/locations/ajman">Ajman</a> · <a href="/locations/ras-al-khaimah">Ras Al Khaimah</a> · <a href="/locations/fujairah">Fujairah</a> · <a href="/locations/umm-al-quwain">Umm Al Quwain</a></p>
<h3 data-block="faq">Frequently Asked Questions</h3>
<h4>How long does a sofa take to dry?</h4><p>Usually 3–6 hours. Running the AC or a fan speeds it up.</p>
<h4>Can you remove all stains?</h4><p>Most everyday stains come out completely. Very old or set-in stains usually fade significantly; we''ll tell you honestly what to expect before we start.</p>
<h4>Do you clean leather sofas?</h4><p>Yes. Leather is cleaned with a dedicated leather cleaner and conditioned — no water extraction.</p>
<h4>Is it safe for kids and pets?</h4><p>Yes. Our cleaning solutions are non-toxic and fully rinsed out with hot-water extraction.</p>', 'Sofa Cleaning in Dubai and Across the UAE', 'Sofa Cleaning Dubai | Deep Sofa Shampoo from AED 149 | Matla Al Anwar', 'Professional sofa cleaning in Dubai, Sharjah, Ajman, Abu Dhabi & all UAE. Deep shampoo & hot-water extraction from AED 149. Same-day slots, child & pet safe.', 4),
  ('upholstery-mattress-cleaning', 'Upholstery & Mattress Cleaning', 'Dining chairs, headboards, mattresses, cushions and curtains sanitised and refreshed at your home.', 'bed', '<h2>Sleep and sit on something clean</h2>
<p><strong>Fresh walls. Spotless sofas.</strong></p>
<p>Mattresses collect dust mites, dead skin and sweat that you can''t see but can feel — especially if anyone at home has allergies. We vacuum with HEPA filtration, treat stains, sanitise and extract, leaving your mattress fresh and hygienic.</p><p>The same care goes into dining chairs, headboards, ottomans and curtains.</p>
<h3>What We Clean</h3>
<ul><li><p><strong>Mattresses</strong> Single, queen and king — both sides on request.</p></li><li><p><strong>Dining chairs</strong> Fabric seats and backs cleaned and stain-treated.</p></li><li><p><strong>Headboards &amp; ottomans</strong> Upholstered bedroom furniture refreshed in place.</p></li><li><p><strong>Curtains</strong> Steam-cleaned on the rail, no need to take them down.</p></li></ul>
<h3>Packages &amp; Prices</h3>
<ul><li><p><strong>Single mattress</strong> From AED 99.</p></li><li><p><strong>Queen / king mattress</strong> From AED 149.</p></li><li><p><strong>Dining chair</strong> From AED 20 per chair.</p></li><li><p><strong>Curtains</strong> Priced per panel.</p></li></ul>
<p>Final prices are fixed after we see photos or inspect the space. <a href="/pricing">See the full price list</a>.</p>
<h3>How It Works</h3>
<ol><li><p><strong>Send photos or call</strong> Share the rooms, sofa size or area you need done by WhatsApp, phone or the quote form.</p></li><li><p><strong>Get a fixed price</strong> We send a clear quote, or visit for a free inspection on bigger painting jobs.</p></li><li><p><strong>We do the work</strong> Our uniformed team arrives on time, covers furniture and floors, and gets to work.</p></li><li><p><strong>Clean handover</strong> We tidy up, walk you through the finish and only leave when you''re happy.</p></li></ol>
<h3>Why Choose Matla Al Anwar</h3>
<ul><li><p><strong>Fixed, transparent prices</strong> no hidden charges after the quote</p></li><li><p><strong>Trained, uniformed team</strong> painters and cleaners who respect your home</p></li><li><p><strong>Premium materials</strong> Jotun, National Paints, Dulux and safe cleaning solutions</p></li><li><p><strong>Furniture &amp; floor protection</strong> everything covered before we start</p></li><li><p><strong>All 7 emirates</strong> covered from one point of contact</p></li></ul>
<h3 data-block="areas">Areas We Cover</h3>
<p><a href="/locations/dubai">Dubai</a> · <a href="/locations/abu-dhabi">Abu Dhabi</a> · <a href="/locations/sharjah">Sharjah</a> · <a href="/locations/ajman">Ajman</a> · <a href="/locations/ras-al-khaimah">Ras Al Khaimah</a> · <a href="/locations/fujairah">Fujairah</a> · <a href="/locations/umm-al-quwain">Umm Al Quwain</a></p>
<h3 data-block="faq">Frequently Asked Questions</h3>
<h4>How often should a mattress be cleaned?</h4><p>Every 6–12 months, or every 3–6 months for allergy sufferers and homes with pets.</p>
<h4>When can I sleep on it again?</h4><p>Usually after 4–6 hours, once it''s fully dry.</p>
<h4>Do you remove urine stains and smells?</h4><p>Yes. We use enzyme treatments that break down urine and odour, not just mask it.</p>', 'Mattress & Upholstery Cleaning in Dubai and the UAE', 'Mattress & Upholstery Cleaning Dubai | Dust Mite Removal | Matla Al Anwar', 'Mattress cleaning from AED 99 and upholstery cleaning for dining chairs, headboards & curtains in Dubai and across the UAE. Dust-mite removal and sanitising.', 5),
  ('majlis-carpet-cleaning', 'Majlis & Carpet Cleaning', 'Majlis seating, rugs and carpets cleaned on-site with fast-dry equipment — ready for guests the same day.', 'sparkles', '<h2>A fresh majlis, ready for guests</h2>
<p><strong>Fresh walls. Spotless sofas.</strong></p>
<p>Your majlis works hard — family gatherings, Ramadan, Eid and every visit in between. We clean floor cushions, back rests, arm rests and the carpet underneath on-site, with fast-dry machines so the room is ready for guests the same day.</p>
<h3>What We Clean</h3>
<ul><li><p><strong>Majlis seating</strong> Floor cushions, back rests and arm rests, priced per metre.</p></li><li><p><strong>Wall-to-wall carpet</strong> Hot-water extraction for bedrooms, offices and corridors.</p></li><li><p><strong>Rugs</strong> Persian, synthetic and wool rugs cleaned on-site.</p></li><li><p><strong>Stain &amp; odour treatment</strong> Coffee, food and pet stains, plus deodorising.</p></li></ul>
<h3>Packages &amp; Prices</h3>
<ul><li><p><strong>Majlis</strong> From AED 35 per metre.</p></li><li><p><strong>Carpet</strong> Priced per square metre.</p></li><li><p><strong>Rugs</strong> From AED 60 per rug.</p></li><li><p><strong>Majlis + carpet</strong> Ask for a combined price.</p></li></ul>
<p>Final prices are fixed after we see photos or inspect the space. <a href="/pricing">See the full price list</a>.</p>
<h3>How It Works</h3>
<ol><li><p><strong>Send photos or call</strong> Share the rooms, sofa size or area you need done by WhatsApp, phone or the quote form.</p></li><li><p><strong>Get a fixed price</strong> We send a clear quote, or visit for a free inspection on bigger painting jobs.</p></li><li><p><strong>We do the work</strong> Our uniformed team arrives on time, covers furniture and floors, and gets to work.</p></li><li><p><strong>Clean handover</strong> We tidy up, walk you through the finish and only leave when you''re happy.</p></li></ol>
<h3>Why Choose Matla Al Anwar</h3>
<ul><li><p><strong>Fixed, transparent prices</strong> no hidden charges after the quote</p></li><li><p><strong>Trained, uniformed team</strong> painters and cleaners who respect your home</p></li><li><p><strong>Premium materials</strong> Jotun, National Paints, Dulux and safe cleaning solutions</p></li><li><p><strong>Furniture &amp; floor protection</strong> everything covered before we start</p></li><li><p><strong>All 7 emirates</strong> covered from one point of contact</p></li></ul>
<h3 data-block="areas">Areas We Cover</h3>
<p><a href="/locations/dubai">Dubai</a> · <a href="/locations/abu-dhabi">Abu Dhabi</a> · <a href="/locations/sharjah">Sharjah</a> · <a href="/locations/ajman">Ajman</a> · <a href="/locations/ras-al-khaimah">Ras Al Khaimah</a> · <a href="/locations/fujairah">Fujairah</a> · <a href="/locations/umm-al-quwain">Umm Al Quwain</a></p>
<h3 data-block="faq">Frequently Asked Questions</h3>
<h4>How long does majlis cleaning take?</h4><p>Most majlis rooms are done in 2–4 hours and dry within the day.</p>
<h4>Do you clean before Ramadan and Eid?</h4><p>Yes — these are our busiest weeks, so book a few days ahead.</p>
<h4>Can you clean delicate or hand-made rugs?</h4><p>Yes. We test fabrics and colours first and use gentler methods on delicate rugs.</p>', 'Majlis & Carpet Cleaning in Dubai and the UAE', 'Majlis Cleaning & Carpet Shampoo Dubai | Matla Al Anwar', 'Majlis cleaning from AED 35 per metre and carpet shampoo in Dubai, Sharjah, Abu Dhabi & all UAE. On-site, fast-dry, ready for guests the same day.', 6);

