INSERT INTO public.industries (slug, name, description, content_html, sort_order) VALUES
  ('apartments', 'Apartments', 'Move-in and move-out painting, fresh coats between tenants and same-day sofa cleaning for apartments across the UAE.', '<h2>Painting &amp; sofa cleaning for apartments</h2>
<p><strong>Fresh walls. Spotless sofas.</strong></p>
<p>Apartments are where we work most. We know building rules, lift bookings and the landlord-standard finish needed for handover — and we keep noise and mess to a minimum for your neighbours.</p>
<h3>How We Help</h3>
<ul><li><p><strong>Move-out painting</strong> Back to the original colour for your deposit.</p></li><li><p><strong>Feature walls</strong> Add colour to living rooms and bedrooms.</p></li><li><p><strong>Sofa &amp; mattress cleaning</strong> Fresh furniture without moving it out.</p></li><li><p><strong>Fast turnaround</strong> Most 1–2 bedroom jobs done in 1–2 days.</p></li></ul>
<h3>Services We Provide</h3>
<ul><li><p><strong>Interior painting</strong> <a href="/services/interior-painting">Walls, ceilings and trims</a>.</p></li><li><p><strong>Exterior painting</strong> <a href="/services/exterior-painting">Facades and boundary walls</a>.</p></li><li><p><strong>Sofa cleaning</strong> <a href="/services/sofa-cleaning">Deep shampoo and extraction</a>.</p></li><li><p><strong>Mattress &amp; upholstery</strong> <a href="/services/upholstery-mattress-cleaning">Sanitising and stain removal</a>.</p></li></ul>
<h3>Why Choose Matla Al Anwar</h3>
<ul><li><p><strong>Fixed, transparent prices</strong> no hidden charges after the quote</p></li><li><p><strong>Trained, uniformed team</strong> painters and cleaners who respect your home</p></li><li><p><strong>Premium materials</strong> Jotun, National Paints, Dulux and safe cleaning solutions</p></li><li><p><strong>Furniture &amp; floor protection</strong> everything covered before we start</p></li><li><p><strong>All 7 emirates</strong> covered from one point of contact</p></li></ul>
<h3 data-block="areas">Areas We Cover</h3>
<p><a href="/locations/dubai">Dubai</a> · <a href="/locations/abu-dhabi">Abu Dhabi</a> · <a href="/locations/sharjah">Sharjah</a> · <a href="/locations/ajman">Ajman</a> · <a href="/locations/ras-al-khaimah">Ras Al Khaimah</a> · <a href="/locations/fujairah">Fujairah</a> · <a href="/locations/umm-al-quwain">Umm Al Quwain</a></p>
<h3 data-block="faq">Frequently Asked Questions</h3>
<h4>Do you offer regular contracts for apartments?</h4><p>Yes. We offer scheduled painting touch-ups and cleaning visits monthly, quarterly or between tenancies, with fixed rates.</p>
<h4>Can you work outside normal hours?</h4><p>Yes. Evenings, weekends and holidays can be arranged so your home or business isn''t disrupted.</p>', 1),
  ('villas', 'Villas', 'Full villa interior and exterior painting plus sofa, majlis and mattress cleaning for family homes.', '<h2>Painting &amp; sofa cleaning for villas</h2>
