INSERT INTO public.locations (slug, name, arabic, blurb, neighborhoods, response_time, map_x, map_y, body_content, sort_order) VALUES
  ('dubai', 'Dubai', 'دبي', 'Apartment, villa and office painting plus sofa and upholstery cleaning across Dubai — from Marina and JVC towers to Mirdif, Arabian Ranches and Downtown.', 'Dubai Marina, JLT, JVC, Downtown, Business Bay, Al Barsha, Mirdif, Arabian Ranches, Palm Jumeirah, Silicon Oasis, Deira, Bur Dubai', 'Same day', 55, 55, '<h2>Painters and sofa cleaners in Dubai</h2>
<p>Dubai is where most of our team is based, so we can usually offer same-day sofa cleaning and next-day painting starts in areas like Dubai Marina, JLT, JVC, Downtown, Business Bay, Al Barsha, Mirdif and Arabian Ranches.</p>
<p>We know the rules in Dubai''s towers and gated communities — lift bookings, work permits from building management and quiet hours — and we handle the paperwork with you so the job runs smoothly.</p>
<h3>Popular jobs in Dubai</h3>
<ul><li><p>Move-out painting for apartment handovers in Marina, JLT and JVC</p></li><li><p>Villa interior and exterior repaints in Arabian Ranches, Mirdif and The Springs</p></li><li><p>L-shape sofa and majlis cleaning before Ramadan and Eid</p></li></ul>', 1),
  ('abu-dhabi', 'Abu Dhabi', 'أبو ظبي', 'Interior and exterior painting and deep sofa cleaning for homes and offices in Abu Dhabi — Khalifa City, Al Reem, Yas Island, Saadiyat and Mohammed Bin Zayed City.', 'Khalifa City, Al Reem Island, Yas Island, Saadiyat, MBZ City, Al Raha, Corniche', 'Next day', 35, 72, '<h2>Painting and sofa cleaning in Abu Dhabi</h2>
<p>We serve Abu Dhabi homes and businesses on scheduled visit days, covering Khalifa City, Al Reem Island, Yas Island, Saadiyat, Al Raha and Mohammed Bin Zayed City.</p>
<p>Villa painting jobs in Abu Dhabi start after a free inspection, and sofa and mattress cleaning is usually available the next day.</p>', 2),
  ('sharjah', 'Sharjah', 'الشارقة', 'Affordable flat and villa painting and sofa shampooing in Sharjah — Al Nahda, Al Majaz, Al Khan, Muwaileh and Aljada, with same-day slots.', 'Al Nahda, Al Majaz, Al Khan, Al Taawun, Muwaileh, Aljada', 'Same day', 62, 50, '<h2>Affordable painting and sofa cleaning in Sharjah</h2>
<p>Sharjah families and landlords use us for quick, affordable flat repaints and sofa shampooing in Al Nahda, Al Majaz, Al Khan, Al Taawun, Muwaileh and Aljada.</p>
<p>Because Sharjah is close to our Dubai base, same-day sofa cleaning slots are often available.</p>', 3),
  ('ajman', 'Ajman', 'عجمان', 'Wall painting, move-out repainting and fabric sofa cleaning for apartments and villas in Ajman — Al Nuaimiya, Al Rashidiya, Al Jurf and Emirates City.', 'Al Nuaimiya, Al Rashidiya, Al Jurf, Al Rawda, Emirates City', 'Same day', 66, 46, '<h2>Painting and sofa cleaning in Ajman</h2>
<p>From Al Nuaimiya and Al Rashidiya to Al Jurf and Emirates City, we paint apartments and villas in Ajman and clean sofas, mattresses and majlis on-site.</p>
<p>Move-out painting for Ajman tenancies is one of our most-booked jobs — usually finished in a day.</p>', 4),
  ('ras-al-khaimah', 'Ras Al Khaimah', 'رأس الخيمة', 'Villa repainting, exterior weather-shield coatings and sofa and carpet cleaning in Ras Al Khaimah — Al Hamra, Mina Al Arab, Al Nakheel and Al Marjan Island.', 'Al Hamra, Mina Al Arab, Al Nakheel, Al Marjan Island, Khuzam', 'Next day', 76, 30, '<h2>Villa painting and upholstery cleaning in Ras Al Khaimah</h2>
<p>RAK villas and holiday homes in Al Hamra, Mina Al Arab and Al Marjan Island face strong sun and sea air. We use weather-shield exterior coatings and schedule upholstery and carpet cleaning between guest stays.</p>', 5),
  ('fujairah', 'Fujairah', 'الفجيرة', 'Painting and upholstery cleaning on the east coast — Fujairah City, Dibba and Kalba homes, holiday villas and hotels, booked on scheduled visit days.', 'Fujairah City, Dibba, Kalba, Al Faseel, Merashid', 'Scheduled', 88, 42, '<h2>Painting and sofa cleaning in Fujairah</h2>
<p>We visit Fujairah City, Dibba and Kalba on scheduled days for painting projects, holiday-villa refreshes and sofa, mattress and curtain cleaning. Book a few days ahead and we''ll plan the route.</p>', 6),
  ('umm-al-quwain', 'Umm Al Quwain', 'أم القيوين', 'Apartment and villa painting plus sofa, mattress and curtain cleaning in Umm Al Quwain — Al Salamah, Al Raas, UAQ Marina and the Old Town.', 'Al Salamah, Al Raas, UAQ Marina, Old Town, Al Humrah', 'Next day', 70, 40, '<h2>Painting and sofa cleaning in Umm Al Quwain</h2>
<p>From Al Salamah to UAQ Marina, we repaint apartments and villas and clean sofas, majlis and mattresses for UAQ families, usually on next-day slots.</p>', 7);

-- FAQs ('pages' = where each FAQ shows; blog_post_slug = FAQ for one blog post)
INSERT INTO public.faqs (question, answer, pages, blog_post_slug, sort_order) VALUES
  ('How much does it cost to paint an apartment in Dubai?', 'Our apartment painting starts from AED 650 for a studio, AED 950 for a 1-bedroom and AED 1,400 for a 2-bedroom, including walls, ceilings, two coats of paint and furniture covering. Villas start from AED 3,500. We confirm a fixed price after a free inspection.', 'home,faq,fleet,services', NULL, 1),
  ('How much is sofa cleaning?', 'Sofa cleaning starts from AED 149 for a 3-seater and AED 249 for an L-shape or 5–7 seater sofa. Majlis cleaning is priced per metre and mattresses start from AED 99.', 'home,faq,fleet,services', NULL, 2),
  ('Which areas do you cover?', 'We work across all seven emirates — Dubai, Abu Dhabi, Sharjah, Ajman, Ras Al Khaimah, Fujairah and Umm Al Quwain. Dubai, Sharjah and Ajman usually get same-day slots.', 'home,faq,locations,contact', NULL, 3),
  ('How long does painting take, and can we stay at home?', 'A studio or 1-bedroom is usually finished in 1–2 days and a villa in 3–6 days. We use low-odour, quick-drying paints and cover all furniture and floors, so most families stay at home while we work.', 'home,faq,services', NULL, 4),
  ('How long does a sofa take to dry after cleaning?', 'With our hot-water extraction machines most fabric sofas are dry in 3–6 hours. Opening windows or running the AC speeds it up.', 'home,faq,services', NULL, 5),
  ('Which paint brands do you use?', 'We use trusted brands such as Jotun, National Paints and Dulux. You can choose the brand, finish (matt, silk or gloss) and colour, and we can bring colour charts to your home.', 'faq,services,about', NULL, 6),
  ('How do I get a quote?', 'Send us photos on WhatsApp, call +971 50 000 0000, or fill in the contact form. We reply quickly with a price, or book a free site inspection for bigger jobs.', 'faq,contact,fleet', NULL, 7),
  ('Is the price fixed?', 'Yes. Once we''ve seen photos or inspected the space, the quote we give is the price you pay — paint, materials and labour included.', 'faq,fleet,contact,about', NULL, 8),
  ('Do I need to move furniture before you start?', 'No. Our team moves furniture to the centre of each room and covers it along with floors and fittings, then puts everything back when we finish.', 'faq,services', NULL, 9),
  ('Are your cleaning products safe for children and pets?', 'Yes. We use professional, fabric-safe and non-toxic solutions, and rinse thoroughly with hot-water extraction so no residue is left behind.', 'faq,services,industries', NULL, 10),
  ('Do you work with landlords, offices and holiday homes?', 'Yes. We offer turnaround painting between tenants, after-hours office work and regular cleaning for holiday homes, with consistent pricing across multiple units.', 'faq,industries,about', NULL, 11),
  ('Do you work on weekends and evenings?', 'Yes. We''re open 7 days a week, and evening or weekend slots can be arranged for offices, shops and restaurants.', 'faq,contact,locations', NULL, 12),
  ('Is paint included in the price?', 'Yes. Our apartment painting prices include paint, two coats and furniture covering.', '', 'apartment-painting-cost-dubai', 13),
  ('Do I need to empty the apartment?', 'No. We move furniture to the middle of each room and cover it.', '', 'apartment-painting-cost-dubai', 14),
  ('How long does professional sofa cleaning take?', 'About 1–2 hours for a 3-seater, and 3–6 hours to dry.', '', 'how-often-clean-sofa-uae', 15),
  ('Can you paint the day before handover?', 'Yes. Most studios and 1-bedrooms are done in one day, and the paint is dry the same evening.', '', 'move-out-painting-dubai-deposit', 16);

-- Blog posts
INSERT INTO public.blog_posts (slug, title, excerpt, content_html, meta_title, meta_description, published, published_at) VALUES ('apartment-painting-cost-dubai', 'How Much Does It Cost to Paint an Apartment in Dubai?', 'Studio, 1-bedroom, 2-bedroom and villa painting prices in Dubai explained — plus what changes the price and how to avoid surprise charges.', '<p>If you''re moving out, moving in or just tired of scuffed walls, the first question is always the same: <strong>how much will it cost?</strong> Here''s a clear guide to apartment and villa painting prices in Dubai, and what makes a quote go up or down.</p>
<h2>Typical painting prices in Dubai</h2>
<table><thead><tr><th>Property</th><th>Starting price</th><th>Typical time</th></tr></thead><tbody>
<tr><td>Studio</td><td>AED 650</td><td>1 day</td></tr>
<tr><td>1 bedroom apartment</td><td>AED 950</td><td>1–2 days</td></tr>
<tr><td>2 bedroom apartment</td><td>AED 1,400</td><td>2 days</td></tr>
<tr><td>3 bedroom apartment</td><td>AED 1,900</td><td>2–3 days</td></tr>
<tr><td>Villa (3–5 bedrooms)</td><td>AED 3,500</td><td>3–6 days</td></tr>
</tbody></table>
<p>These prices include paint, two coats on walls and ceilings, minor crack filling and covering your furniture and floors.</p>
<h2>What changes the price?</h2>
<h3>1. Wall condition</h3>
<p>Walls with lots of nail holes, cracks or damp patches need more preparation. Light preparation is included; heavy repairs are quoted separately.</p>
<h3>2. Colour change</h3>
<p>Going from a dark colour back to white usually needs a primer or a third coat. Staying with the same colour (common for move-out painting) is the cheapest option.</p>
<h3>3. Ceiling height and stairwells</h3>
<p>Double-height living rooms and villa stairwells need towers or extra equipment and take longer.</p>
<h3>4. Paint brand and finish</h3>
<p>Jotun, National Paints and Dulux all have budget and premium ranges. Washable silk or satin finishes cost a little more than standard matt but are easier to clean.</p>
<h2>How to avoid surprise charges</h2>
<ul><li><p>Send clear photos of every room on WhatsApp, including any damage.</p></li><li><p>Confirm the paint brand, number of coats and whether ceilings, doors and trims are included.</p></li><li><p>Ask for a fixed price in writing before work starts.</p></li></ul>
<p>Want an exact price? <a href="/contact">Send us photos</a> and we''ll reply with a fixed quote, or see our full <a href="/pricing">price list</a>.</p>', 'Apartment Painting Cost in Dubai (Studio, 1BR, 2BR & Villa) | Matla Al Anwar', 'What does it cost to paint an apartment in Dubai? Studio from AED 650, 1BR from AED 950, 2BR from AED 1,400 and villas from AED 3,500 — and what affects the price.', true, now() - interval '10 days');
INSERT INTO public.blog_posts (slug, title, excerpt, content_html, meta_title, meta_description, published, published_at) VALUES ('how-often-clean-sofa-uae', 'How Often Should You Clean Your Sofa in the UAE?', 'Sand, dust, AC and humidity make UAE sofas dirtier faster. Here''s how often to deep clean, plus simple weekly habits that keep fabric fresh.', '<p>Your sofa is probably the most-used piece of furniture in your home — and in the UAE it collects more than you''d think. Fine sand blows in, AC circulates dust, and humidity helps odours and bacteria settle into the fabric.</p>
<h2>The short answer</h2>
<ul><li><p><strong>Every 6–12 months</strong> for most homes.</p></li><li><p><strong>Every 3–6 months</strong> if you have children, pets, allergies or a light-coloured fabric sofa.</p></li><li><p><strong>Before and after big occasions</strong> like Ramadan, Eid or hosting family.</p></li></ul>
<h2>Signs your sofa needs a deep clean</h2>
<ul><li><p>Arm rests and head areas look darker or shiny.</p></li><li><p>There''s a lingering smell even after airing the room.</p></li><li><p>Someone at home sneezes more when sitting on it.</p></li><li><p>Stains have spread or left rings after spot cleaning.</p></li></ul>
<h2>Weekly habits that help</h2>
<h3>Vacuum with an upholstery brush</h3>
<p>A quick vacuum once a week removes sand and crumbs before they work into the fibres.</p>
<h3>Rotate and flip cushions</h3>
<p>This spreads wear evenly and stops one seat from sagging and darkening.</p>
<h3>Blot spills straight away</h3>
<p>Blot — don''t rub — with a clean white cloth. Rubbing pushes the stain deeper and spreads it.</p>
<h2>Why professional cleaning is different</h2>
<p>Hot-water extraction rinses shampoo and dirt out of the fabric and sucks it away. Home methods often leave soap residue behind, which attracts dirt and makes the sofa look dirty again quickly.</p>
<p>Ready for a fresh sofa? <a href="/services/sofa-cleaning">See our sofa cleaning service</a> — 3-seaters start from AED 149.</p>', 'How Often Should You Clean Your Sofa? UAE Guide | Matla Al Anwar', 'How often to deep clean a sofa in Dubai and the UAE, signs it needs cleaning, and easy weekly care tips to keep fabric sofas fresh between professional cleans.', true, now() - interval '7 days');
INSERT INTO public.blog_posts (slug, title, excerpt, content_html, meta_title, meta_description, published, published_at) VALUES ('best-paint-colours-finishes-uae-homes', 'Best Paint Colours and Finishes for UAE Homes', 'Which colours keep rooms feeling cool, which finishes survive kids and sand, and what works best for exterior walls in the Gulf climate.', '<p>The right paint makes a room feel bigger, cooler and easier to live in. The wrong one shows every fingerprint and fades in a summer. Here''s what works best in UAE homes.</p>
<h2>Colours that work in the UAE</h2>
<h3>Warm whites and soft neutrals</h3>
<p>Off-whites, warm greys and sand tones reflect light without feeling cold, and they suit both modern apartments and traditional villas.</p>
<h3>Cool accent colours</h3>
<p>Soft blues, sage greens and deep navy feature walls make rooms feel calm and cool — a good balance to strong sunlight.</p>
<h3>What to avoid</h3>
<p>Very dark colours on sun-facing walls can fade quickly, and bright pure white can feel harsh in strong daylight.</p>
<h2>Which finish for which room?</h2>
<table><thead><tr><th>Room</th><th>Recommended finish</th><th>Why</th></tr></thead><tbody>
<tr><td>Living & bedrooms</td><td>Matt or soft silk</td><td>Hides small wall imperfections</td></tr>
<tr><td>Kids'' rooms & corridors</td><td>Silk / satin washable</td><td>Easy to wipe clean</td></tr>
<tr><td>Kitchens & bathrooms</td><td>Satin or semi-gloss, anti-mould</td><td>Resists steam and grease</td></tr>
<tr><td>Doors & trims</td><td>Gloss or semi-gloss enamel</td><td>Durable and easy to clean</td></tr>
</tbody></table>
<h2>Exterior paint for the Gulf climate</h2>
<p>Use weather-shield or elastomeric exterior paints with UV protection. Good preparation — pressure washing, crack repair and primer — matters as much as the paint itself.</p>
<p>Not sure what to choose? We can bring colour fans from Jotun, National Paints and Dulux to your home. <a href="/contact">Book a free visit</a>.</p>', 'Best Paint Colours & Finishes for Dubai and UAE Homes | Matla Al Anwar', 'Choosing paint for a UAE home? The best colours for bright, cool rooms, which finish to use in each room, and exterior paint that survives the Gulf climate.', true, now() - interval '4 days');
INSERT INTO public.blog_posts (slug, title, excerpt, content_html, meta_title, meta_description, published, published_at) VALUES ('move-out-painting-dubai-deposit', 'Move-Out Painting in Dubai: How to Get Your Deposit Back', 'What landlords expect at handover, whether you have to repaint, and a simple checklist to get your security deposit back without stress.', '<p>Many tenancy contracts in Dubai, Sharjah and Ajman say the apartment must be returned "in its original condition" — which usually means freshly painted in the original colour. If it isn''t, the landlord may deduct painting costs from your security deposit, often at a higher rate than doing it yourself.</p>
<h2>Do you have to repaint?</h2>
<p>Check your tenancy contract and any handover checklist from the agent. If it mentions painting or "original condition", plan to repaint — especially if you''ve lived there more than a year, hung frames or used colour on any walls.</p>
<h2>What landlords check at handover</h2>
<ul><li><p>Walls are clean, even and in the original colour (usually white).</p></li><li><p>Nail and screw holes are filled.</p></li><li><p>No marks behind beds, sofas or TV units.</p></li><li><p>Ceilings, especially in kitchens and bathrooms, are free of stains.</p></li></ul>
<h2>How much does move-out painting cost?</h2>
<p>With Matla Al Anwar, move-out painting starts from <strong>AED 650 for a studio</strong>, <strong>AED 950 for a 1-bedroom</strong> and <strong>AED 1,400 for a 2-bedroom</strong>. Most jobs take a single day.</p>
<h2>Your move-out checklist</h2>
<ol><li><p>Book painting for after your furniture is moved out.</p></li><li><p>Ask the painters to fill all holes and repaint in the original colour.</p></li><li><p>Book sofa, mattress or carpet cleaning if furniture stays with the apartment.</p></li><li><p>Take photos of every room after the work is done.</p></li><li><p>Attend the handover inspection with your photos.</p></li></ol>
<p>Moving soon? <a href="/services/apartment-painting">See our move-out painting service</a> or <a href="/contact">send us your handover date</a>.</p>', 'Move-Out Painting Dubai: Get Your Security Deposit Back | Matla Al Anwar', 'Do you have to repaint when moving out in Dubai? What landlords check at handover, how much move-out painting costs and a checklist to get your deposit back.', true, now() - interval '2 days');

